# Translates Unity's Metal compute kernels (MSL generated by HLSLcc) to HLSL
# for cs_5_0, with the D3D11 resource bindings Unity needs to drive them.
#
# The kernel body is kept as written, like msl2hlsl.py does for vertex and
# fragment programs. Kernel arguments become globals: constant buffers (b#),
# sampled textures and read-only buffers (t#), samplers (s#), and written
# textures and buffers (u#, the "outBuffers" Unity binds as UAVs).
# threadgroup arrays become groupshared, Metal atomics Interlocked* calls.
import re

import msl2hlsl
from msl2hlsl import Unsupported, split_args, split_type, rewrite_calls, cbuffer_layout, parse_members

SYSTEM_VALUES = {
    "thread_position_in_grid": ("uint3", "SV_DispatchThreadID"),
    "thread_position_in_threadgroup": ("uint3", "SV_GroupThreadID"),
    "threadgroup_position_in_grid": ("uint3", "SV_GroupID"),
    "thread_index_in_threadgroup": ("uint", "SV_GroupIndex"),
}
TEXTURES = {"texture2d": ("Texture2D", 2), "texture3d": ("Texture3D", 3), "texture2d_array": ("Texture2DArray", 5)}
RW_TEXTURES = {"texture2d": ("RWTexture2D", 2), "texture3d": ("RWTexture3D", 3), "texture2d_array": ("RWTexture2DArray", 5)}

UNPACK_HALF2 = """float2 unpackHalf2(uint u)
{
    return float2(f16tof32(u), f16tof32(u >> 16));
}
"""
BITFIELD_INSERT = """uint bitFieldInsert(uint width, uint offset, uint src2, uint src3)
{
    uint bitmask = (((1u << width) - 1u) << offset) & 0xffffffffu;
    return ((src2 << offset) & bitmask) | (src3 & ~bitmask);
}
"""


class Binding:
    """One resource of the kernel: kind is cb, tex, sampler, rwtex, buf or rwbuf."""

    def __init__(self, kind, name, metal_slot, dim=-1):
        self.kind, self.name, self.metal_slot, self.dim = kind, name, metal_slot, dim
        self.register = None


def parse_kernel(msl):
    m = re.search(r"kernel\s+void\s+computeMain\s*\((.*?)\)\s*\{", msl, re.S)
    if not m:
        raise Unsupported("no computeMain")
    head = msl[:m.start()]
    body_start = m.end()
    depth, i = 1, body_start
    while depth:
        depth += {"{": 1, "}": -1}.get(msl[i], 0)
        i += 1
    body = msl[body_start:i - 1]
    structs = {sm.group(1): sm.group(2) for sm in re.finditer(r"struct\s+(\w+)\s*\{(.*?)\};", head, re.S)}
    # HLSLcc's immediate constant buffers: constant float4 ImmCB_0[4] = { ... };
    parse_kernel.immediates = [f"static const {im.group(1)} {im.group(2)}[{im.group(3)}] = {{{im.group(4)}}};"
                               for im in re.finditer(r"constant\s+(\w+)\s+(\w+)\[(\d+)\]\s*=\s*\{(.*?)\};", head, re.S)]
    bindings, sysvals = [], []
    for arg in split_args(m.group(1)):
        arg = " ".join(arg.split())
        a = re.fullmatch(r"constant (\w+)& (\w+) \[\[ buffer\((\d+)\) \]\]", arg)
        if a:
            b = Binding("cb", a.group(2), int(a.group(3)))
            b.type = a.group(1)
            bindings.append(b)
            continue
        a = re.fullmatch(r"sampler (\w+) \[\[ sampler \((\d+)\) \]\]", arg)
        if a:
            bindings.append(Binding("sampler", a.group(1), int(a.group(2))))
            continue
        a = re.fullmatch(r"(texture2d|texture3d|texture2d_array)<float, access::(sample|read|write) ?> (\w+) \[\[ texture\((\d+)\) \]\]", arg)
        if a:
            kind = "rwtex" if a.group(2) == "write" else "tex"
            b = Binding(kind, a.group(3), int(a.group(4)))
            b.texkind = a.group(1)
            b.dim = (RW_TEXTURES if kind == "rwtex" else TEXTURES)[a.group(1)][1]
            bindings.append(b)
            continue
        a = re.fullmatch(r"(const )?device (\w+) \*(\w+) \[\[ buffer\((\d+)\) \]\]", arg)
        if a:
            b = Binding("buf" if a.group(1) else "rwbuf", a.group(3), int(a.group(4)))
            b.type = a.group(2)
            bindings.append(b)
            continue
        a = re.fullmatch(r"(uint3?) (\w+) \[\[ (\w+) \]\]", arg)
        if a and a.group(3) in SYSTEM_VALUES:
            sysvals.append((SYSTEM_VALUES[a.group(3)][0], a.group(2), SYSTEM_VALUES[a.group(3)][1]))
            continue
        raise Unsupported(f"kernel argument {arg}")
    return structs, bindings, sysvals, body


def rewrite_kernel_body(body, bindings):
    texkinds = {b.name: b.texkind for b in bindings if b.kind in ("tex", "rwtex")}
    shared = []

    def groupshared(mm):
        shared.append(f"groupshared {mm.group(1)} {mm.group(2)}[{mm.group(3)}];")
        return ""

    b = re.sub(r"threadgroup\s+(\w+)\s+(\w+)\[(\d+)\];", groupshared, body)
    b = re.sub(r"threadgroup_barrier\([^)]*\);", "GroupMemoryBarrierWithGroupSync();", b)
    # atomic_fetch_add_explicit(reinterpret_cast<... atomic_uint *>(&X), v, order) -> InterlockedAdd(X, v)
    b = re.sub(r"atomic_fetch_add_explicit\(reinterpret_cast<\s*(?:device|threadgroup)\s+atomic_(?:uint|int)\s*\*\s*>\(&(.*?)\),\s*(.*?),\s*memory_order::\w+\)",
               r"InterlockedAdd(\1, \2)", b)
    if "atomic_" in b:
        raise Unsupported("atomic operation")
    # half packing (GaussianDownsample): helpers emitted when used
    b = rewrite_calls(b, r"\bas_type<half2>\(", lambda m, a: f"unpackHalf2({a[0]})")
    b = rewrite_calls(b, r"\bas_type<uint>\(", lambda m, a: as_uint(a[0]))
    # texture writes and reads
    b = rewrite_calls(b, r"\b(\w+)\.write\(", lambda m, a: tex_write(m.group(1), a, texkinds))
    b = rewrite_calls(b, r"\b(\w+)\.read\(", lambda m, a: tex_read(m.group(1), a, texkinds))
    b = rewrite_calls(b, r"\b(\w+)\.gather\(", lambda m, a: tex_gather(m.group(1), a, texkinds))
    for cb in [x.name for x in bindings if x.kind == "cb"]:
        b = re.sub(rf"\b{cb}\.", "", b)
    b = re.sub(r"\b(\w+)\[(.*?)\]\.value\[", r"\1[\2].value[", b)
    body = msl2hlsl.rewrite_body(b, [], texkinds)
    return body, shared, msl2hlsl.rewrite_body.inline_samplers


def as_uint(arg):
    m = re.fullmatch(r"half2\((.*)\)", arg, re.S)
    if m:
        lo, hi = split_args(m.group(1))
        return f"(f32tof16({lo}) | (f32tof16({hi}) << 16))"
    return f"asuint({arg})"


def tex_write(name, args, texkinds):
    kind = texkinds.get(name)
    value, coord = args[0], args[1]
    if kind == "texture2d_array":
        return f"{name}[uint3({coord}, {args[2]})] = {value}"
    if kind == "texture3d":
        return f"{name}[uint3({coord})] = {value}"
    return f"{name}[uint2({coord})] = {value}"


def tex_read(name, args, texkinds):
    kind = texkinds.get(name, "texture2d")
    lod = args[-1] if (kind == "texture2d" and len(args) > 1) or (kind != "texture2d" and len(args) > 2) else "0"
    if kind == "texture3d":
        return f"{name}.Load(int4(int3({args[0]}), int({lod})))"
    if kind == "texture2d_array":
        return f"{name}.Load(int4(int2({args[0]}), int({args[1]}), int({lod})))"
    return f"{name}.Load(int3(int2({args[0]}), int({lod})))"


def tex_gather(name, args, texkinds):
    comp = "Red"
    if texkinds.get(name) == "texture2d_array":
        args = [args[0], f"float3({args[1]}, {args[2]})"] + args[3:]
    rest = args[2:]
    if rest and rest[-1].startswith("component::"):
        comp = {"x": "Red", "y": "Green", "z": "Blue", "w": "Alpha"}[rest[-1].split("::")[1]]
        rest = rest[:-1]
    return f"{name}.Gather{comp}({', '.join(args[:2] + rest)})"


def struct_hlsl(name, members_text):
    return f"struct {name}\n{{{members_text}}};\n"


def translate(msl, thread_group_size):
    """Returns (hlsl, bindings, inline samplers)."""
    msl = msl.replace("\0", "")
    structs, bindings, sysvals, body = parse_kernel(msl)
    body, shared, inline = rewrite_kernel_body(body, bindings)

    # registers: t for read-only textures and buffers, u for writes, s and b in order
    counters = {"t": 0, "u": 0, "s": 0, "b": 0}
    space = {"cb": "b", "tex": "t", "buf": "t", "sampler": "s", "rwtex": "u", "rwbuf": "u"}
    for b in sorted(bindings, key=lambda x: (space[x.kind], x.metal_slot)):
        r = space[b.kind]
        b.register = counters[r]
        counters[r] += 1

    out = []
    out.extend(parse_kernel.immediates)
    if "bitFieldInsert" in body:
        out.append(BITFIELD_INSERT)
    if "unpackHalf2" in body:
        out.append(UNPACK_HALF2)
    cb_types = {b.type for b in bindings if b.kind == "cb"}
    for sname, text in structs.items():
        if sname not in cb_types:
            out.append(struct_hlsl(sname, text))
    for b in bindings:
        if b.kind == "cb":
            members = parse_members(structs[b.type])
            layout, size = cbuffer_layout(members)
            if any(mb.array for mb, _ in layout):
                # Metal indexes arrays as flat memory (HLSLcc may read past an
                # array's end into the next member): one float4 array does too
                if any(split_type(mb.type) != ("float", 4) for mb, off in layout if mb.array):
                    raise Unsupported("non-float4 array in compute constant buffer")
                raw = f"{b.name}_raw"
                out.append(f"cbuffer {b.name} : register(b{b.register})\n{{\n    float4 {raw}[{size // 16}] : packoffset(c0);\n}};\n")
                for mb, off in layout:
                    if mb.array:
                        body = re.sub(rf"\b{mb.name}\[", f"{raw}[{off // 16} + ", body)
                    else:
                        base, n = split_type(mb.type)
                        if base != "float":
                            raise Unsupported("non-float member next to an array")
                        first = (off % 16) // 4
                        body = re.sub(rf"\b{mb.name}\b", f"{raw}[{off // 16}].{'xyzw'[first:first + n]}", body)
                continue
            lines = []
            for mb, off in layout:
                comp = "xyzw"[(off % 16) // 4]
                lines.append(f"    {mb.type.replace('half', 'float')} {mb.name} : packoffset(c{off // 16}.{comp});")
            out.append(f"cbuffer {b.name} : register(b{b.register})\n{{\n" + "\n".join(lines) + "\n};\n")
        elif b.kind == "tex":
            out.append(f"{TEXTURES[b.texkind][0]}<float4> {b.name} : register(t{b.register});")
        elif b.kind == "rwtex":
            out.append(f"{RW_TEXTURES[b.texkind][0]}<float4> {b.name} : register(u{b.register});")
        elif b.kind == "sampler":
            out.append(f"SamplerState {b.name} : register(s{b.register});")
        elif b.kind == "buf":
            out.append(f"StructuredBuffer<{b.type}> {b.name} : register(t{b.register});")
        elif b.kind == "rwbuf":
            out.append(f"RWStructuredBuffer<{b.type}> {b.name} : register(u{b.register});")
    inline_regs = []
    for i, name in enumerate(inline):  # left unbound: see convert_compute.py
        out.append(f"SamplerState {name} : register(s{15 - i});")
        inline_regs.append((name, 15 - i))
    out.extend(shared)
    x, y, z = thread_group_size
    params = ", ".join(f"{t} {n} : {sem}" for t, n, sem in sysvals)
    out.append(f"\n[numthreads({x}, {y}, {z})]\nvoid main({params})\n{{{body}}}\n")
    return "\n".join(out), bindings, inline_regs
